var t=[{title:`Pourquoi les épaules varient`,text:`L’épaule a une grande amplitude de mouvement et s’appuie sur beaucoup de muscles pour rester stable. Lever les bras au-dessus de la tête, les positions profondes de développé et les mouvements rapides peuvent se ressentir très différemment d’une personne à l’autre. Un mouvement restreint ou douloureux vous renseigne sur les exercices à choisir. Il ne prouve pas que vous avez une blessure particulière.`},{title:`Adapter l’exercice`,text:`Si un développé militaire à la barre vous gêne, essayez un développé aux haltères en prise neutre, un rowing avec appui ou une pompe contre un mur. Changez la profondeur ou la direction avant d’ajouter de la résistance. Les exercices de traction sont un bon complément des développés, mais aucun rapport fixe entre poussée et traction ne guérit une douleur d’épaule.`},{title:`Contrôle et exposition graduelle`,text:`Pendant que vous apprenez un mouvement, utilisez des répétitions lentes et contrôlées, une amplitude confortable et des charges légères. Développer la force des épaules peut demander un travail progressivement plus difficile, mais cette progression ne doit pas aggraver vos symptômes. Forcer un étirement malgré la douleur ou retester sans cesse de lourds mouvements au-dessus de la tête ne vous fera pas avancer plus vite.`},{title:`Signes d’alerte`,text:`Demandez rapidement un avis médical en cas de douleur intense après une chute, de bras que vous ne pouvez pas bouger, de déformation visible, de gonflement important ou de nouvel engourdissement qui ne passe pas. Les symptômes qui ne s’améliorent pas nécessitent aussi l’examen d’un professionnel.`},{title:`Avec TrainUp`,text:`Ajoutez votre épaule dans les limitations de Profil, avec des notes, et gardez votre liste d’équipement à jour. Le programme ne choisit alors que des exercices adaptés à vos limitations, votre équipement, votre niveau et votre coordination. Si un exercice fait mal pendant une séance, appuyez sur « J’ai mal » pour y mettre fin aussitôt. Il reste hors de vos programmes jusqu’à ce que vous le réactiviez depuis Profil. Remplacer des exercices de cette façon ne traite pas un conflit sous-acromial, une atteinte de la coiffe des rotateurs ni aucune autre affection précise.`}];var r=[{label:`NHS : douleur à l’épaule et signes d’alerte`,url:`https://www.nhs.uk/symptoms/shoulder-pain/`},{label:`Prise de position 2026 de l’ACSM`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var n={sections:t,sources:r};export{n as default,t as sections,r as sources};